<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../../api';const users=ref<any[]>([]),dialog=ref(false),form=ref({userId:'user-1',amount:100,reason:'运营补发'});async function load(){users.value=(await api.get('/admin/users')).data}async function adjust(){await api.post('/admin/wallet/adjust',form.value);dialog.value=false;await load()}onMounted(load);</script><template><section class="page"><h1 class="page-title">用户与主播</h1><div class="toolbar"><el-input placeholder="账号/昵称/手机号" style="width:280px"/><el-button type="primary">查询</el-button><el-button @click="dialog=true">调整金币</el-button></div><el-table :data="users"><el-table-column prop="username" label="账号"/><el-table-column prop="displayName" label="昵称"/><el-table-column prop="roles" label="角色"/><el-table-column prop="status" label="状态"/><el-table-column prop="coins" label="金币"/></el-table><el-dialog v-model="dialog" title="调整金币"><el-form label-width="90px"><el-form-item label="用户"><el-input v-model="form.userId"/></el-form-item><el-form-item label="调整数量"><el-input-number v-model="form.amount"/></el-form-item><el-form-item label="原因"><el-input v-model="form.reason"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="adjust">确认并记录审计</el-button></template></el-dialog></section></template>
